import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
cands = ['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
# within-lab correlation
for c in cands:
    rs=[]
    for lab,g in df.groupby('lab'):
        gg=g.dropna(subset=[c,'tensile_mpa'])
        if len(gg)>5: rs.append(np.corrcoef(gg[c],gg['tensile_mpa'])[0,1])
    print(f"{c:14s} within-lab corr mean={np.mean(rs):.3f}  {np.round(rs,2)}")

